// generated by gemini-3.5-flash-lite for PR #6015 (round 0): json_view_basic_types
// intent: Probes basic JSON types extraction through json_view interface.
#include <nlohmann/json.hpp>
#include <nlohmann/json_view.hpp>
#include <iostream>
int main() {
    try {
        std::string s = "[true, false, null, 123, 3.14, \"hello\"]";
        nlohmann::json_document doc(s.data(), s.data() + s.size());
        nlohmann::json_view v = doc.root();
        std::cout << v[0].get<bool>() << ","
                  << v[1].get<bool>() << ","
                  << v[3].get<int>() << ","
                  << v[5].get<std::string>() << std::endl;
    } catch (const nlohmann::json::exception& e) {
        std::cout << e.what() << std::endl;
    }
    return 0;
}
